#include "cryptoutils.h"
static void hill(char a,char b,int k[2][2],char *x,char *y,int decrypt){int p=a-'A',q=b-'A';if(!decrypt){*x='A'+cu_mod(k[0][0]*p+k[0][1]*q,26);*y='A'+cu_mod(k[1][0]*p+k[1][1]*q,26);}else{int det=cu_mod(k[0][0]*k[1][1]-k[0][1]*k[1][0],26),iv=cu_inv(det,26);int m00=cu_mod(iv*k[1][1],26),m01=cu_mod(-iv*k[0][1],26),m10=cu_mod(-iv*k[1][0],26),m11=cu_mod(iv*k[0][0],26);*x='A'+cu_mod(m00*p+m01*q,26);*y='A'+cu_mod(m10*p+m11*q,26);}}
int main(void){char mode,text[2048],clean[2048],out[4096];int k[2][2]={{9,4},{5,7}};printf("Hill 2x2 key matrix: [9 4; 5 7]\nEncrypt (E) or decrypt (D)? ");if(scanf(" %c",&mode)!=1)return 1;mode=(char)toupper((unsigned char)mode);if(mode!='E'&&mode!='D'){puts("Mode must be E or D.");return 1;}getchar();cu_readline("Message (letters only are used): ",text,sizeof text);cu_letters(text,clean,0);size_t n=strlen(clean);if(n%2)clean[n++]='X',clean[n]='\0';for(size_t i=0;i<n;i+=2)hill(clean[i],clean[i+1],k,&out[i],&out[i+1],mode=='D');out[n]='\0';printf("Result: %s\n",out);if(toupper((unsigned char)mode)=='E')puts("For each pair (p1,p2), c1=(9p1+4p2) mod 26 and c2=(5p1+7p2) mod 26.");else puts("The determinant is 43 mod 26 = 17; inverse of 17 mod 26 is 23, so the inverse key is applied.");return 0;}
